import{_ as e,l as d,o as a,b as o,d as l,f as s,m as p,j as g,q as n}from"./chunks/framework.Tf23FRXt.js";const c="/assets/resolution.cGCtnKvW.jpg",r="/assets/hires.CqHefPmc.jpg",v="/assets/2e57b1748fb8e9e87b2f901c3ace8182a8a02e.CMB-3sp3.jpg",u="/assets/301f5e8872cc2dbb8406e99753346b9825a897.CAwmbj7J.jpg",m="/assets/set2.BtUkQ9iw.jpg",b="/assets/MovementSettings.CK8HjQsV.jpg",_="/assets/26d2deb74f076c2addefd6e1a836e8b1c5fc41.DfZvq43Y.jpg",f="/assets/0b37f6b105d72e88b3e0a00abb1093cd7709dc.D16GFM7P.jpg",h="/assets/4d0cb98170a1ba6a24e7dc604227aad0863e17.DUU9IHKX.jpg",z=JSON.parse('{"title":"让战斗更方便的设置","description":"","frontmatter":{},"headers":[{"level":2,"title":"显示","slug":"显示","link":"#显示","children":[]},{"level":2,"title":"目标","slug":"目标","link":"#目标","children":[{"level":3,"title":"显示目标所剩的HP","slug":"显示目标所剩的hp","link":"#显示目标所剩的hp","children":[]},{"level":3,"title":"放大目标的咏唱栏","slug":"放大目标的咏唱栏","link":"#放大目标的咏唱栏","children":[]}]},{"level":2,"title":"视角","slug":"视角","link":"#视角","children":[{"level":3,"title":"操作模式与视角","slug":"操作模式与视角","link":"#操作模式与视角","children":[]},{"level":3,"title":"想让视角的移动速度更快一点","slug":"想让视角的移动速度更快一点","link":"#想让视角的移动速度更快一点","children":[]},{"level":3,"title":"视角太低了，看不清机制","slug":"视角太低了-看不清机制","link":"#视角太低了-看不清机制","children":[]}]}],"relativePath":"ui/battle.htm.md","filePath":"ui/battle.md","lastUpdated":1791098838000}'),x={name:"ui/battle.htm.md"},S={class:"guide cols2"},k={class:"guide col grow"};function j(C,i,w,P,y,B){const t=d("CollapseText");return a(),o("div",null,[i[5]||(i[5]=l("h1",{id:"让战斗更方便的设置",tabindex:"-1"},"让战斗更方便的设置",-1)),i[6]||(i[6]=l("p",null,[s("调整界面到自己最舒服的状态，就是改善游戏体验的最佳方法，如果你还没调整过游戏界面的话，先去"),l("a",{href:"/ui/how.htm#改变界面部件的布局"},"调整一下界面"),s("吧！")],-1)),i[7]||(i[7]=l("h2",{id:"显示",tabindex:"-1"},"显示",-1)),l("div",S,[i[4]||(i[4]=l("div",{class:"guide col"},[l("p",null,[l("img",{src:c,alt:"",loading:"lazy"})])],-1)),l("div",k,[i[1]||(i[1]=l("p",null,"如果你是高分辨率屏幕，刚进游戏的时候，游戏界面的 UI 尺寸都会特～别～小。在快捷指令 > 系统 > 系统设置 > 显示设置中，可以针对高分辨率屏幕进行整体的 UI 界面放大。",-1)),p(t,{summary:"放大了，但是文字特别糊"},{default:g(()=>[...i[0]||(i[0]=[l("p",null,[s("放大后如果发现文字边缘模糊，那么需要检查你的系统缩放（在 Windows 设置中，找到显示设置 > 缩放与布局），若系统缩放不为 100%，则需要找到你游戏文件夹中的 "),l("code",null,"ffxiv_dx11.exe"),s(" ，右键 > 属性 > 兼容性 > 更改高 DPI 设置 > 高 DPI 缩放替代，勾选 “替代高 DPI 缩放行为”，同时下拉框改成 “应用程序”，再在游戏中进行缩放调整。")],-1)])]),_:1}),i[2]||(i[2]=l("p",null,[s("另外在界面设置中，也可以单独针对每一个窗口组件进行缩放（快捷键 "),l("code",null,"Ctrl"),s(" + "),l("code",null,"HOME"),s(" ）")],-1)),i[3]||(i[3]=l("p",null,[s("※聊天窗口的文字大小需要单独设置，参见"),l("a",{href:"/basic/communication.htm#聊天窗口的设置"},"这里"),s("。")],-1))])]),i[8]||(i[8]=n('<div class="guide cols2"><div class="guide col"><p><img src="'+r+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>游戏内置了高清的图片和文字资源，但是默认情况下是关闭的，只要你的电脑没有极其严重的性能问题，无论你屏幕分辨率是多少，都推荐使用高清资源：</p><p>在快捷指令 &gt; 系统 &gt; 系统设置 &gt; 图像设置 &gt; 界面分辨率中，类型的下拉菜单中选择 “高分辨率（WQHD/4K 用）”。</p></div></div><h2 id="目标" tabindex="-1">目标</h2><h3 id="显示目标所剩的hp" tabindex="-1">显示目标所剩的 HP</h3><div class="guide cols2"><div class="guide col"><p><img src="'+v+'" alt="" loading="lazy"><br><img src="'+u+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>迷宫副本中，BOSS 会根据剩余血量切换阶段，或者使用特定的攻击，因此关注到 BOSS 血量的玩家也开始变多了。</p><p>为了方便观察，可以启用 “显示所选目标的体力百分比” 的功能。</p><p>在快捷指令 &gt; 系统 &gt; 角色设置 &gt; 界面设置 &gt; 界面中，勾选 “显示所选目标的体力百分比”。</p><p>※开启之后，目标信息和焦点目标信息都会有所显示。</p><p>Tips:<br> 战斗中有多个敌人的时候，将 BOSS 设为焦点，这样在与其他敌人战斗的时候，也可以查看到 BOSS 的剩余血量，非常方便。</p></div></div><h3 id="放大目标的咏唱栏" tabindex="-1">放大目标的咏唱栏</h3><div class="guide cols2"><div class="guide col"><p><img src="'+m+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>在很多战斗中，经常需要通过观察 BOSS 的咏唱栏来进行移动，将目标信息拆分后，就可以单独把目标的咏唱栏拖出来并放大了。</p><p>在快捷指令 &gt; 系统 &gt; 界面设置中，找到 “目标情报” 窗口，并点击它右侧的齿轮按钮。在弹出的窗口中选中 “目标情报分别显示”。</p><p>这样就可以分别设置目标的体力栏，咏唱栏和状态效果的尺寸和位置了。把它们放到显眼的地方吧！</p></div></div><h2 id="视角" tabindex="-1">视角</h2><h3 id="操作模式与视角" tabindex="-1">操作模式与视角</h3><div class="guide cols2"><div class="guide col"><p><img src="'+b+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>如果你有其他游戏的经验，并且觉得 FF14 的操作方式让你觉得不习惯，可以尝试修改移动操作的类型。如果你是第一次玩这种游戏，可以两种模式都体验一下，然后选择一种最舒服的操作模式。</p><p>标准操作模式的特点是相机视角与角色视角分辨控制，而传统模式是根据相机视角控制角色视角。两种模式各有特点，具体的区别和调整方式可以参见<a href="/basic/config.htm#角色设置">游戏设置详解</a>。</p></div></div><h3 id="想让视角的移动速度更快一点" tabindex="-1">想让视角的移动速度更快一点</h3><div class="guide cols2"><div class="guide col"><p><img src="'+_+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>视角的移动速度，可以在 快捷指令 &gt; 系统 &gt; 角色设置 &gt; 操作设置中的全体选项卡中，调整控制视角下的 “使用摇杆时的视角回转速度” 或 “使用键盘时的视角回转速度” 以及 “角色转身速度”。</p><p>视角移动速度只要稍作调整，就会有很大变化，推荐调整到自己觉得舒服的数值。</p><p>推荐数值：视角回转速度推荐调整到 50~80；角色转身速度推荐调整 80~100；数值越高，速度越快。</p></div></div><h3 id="视角太低了-看不清机制" tabindex="-1">视角太低了，看不清机制</h3><p>视角可以在快捷指令 &gt; 系统 &gt; 角色设置 &gt; 操作设置中的全体选项卡中，控制视角下的 “第三人称视角俯视角度” 调整。调整过俯视视角之后，就可能能更容易看清画面，也更容易躲开敌人的攻击了，如果觉得看着不舒服的话，就调整一下视角吧。</p><div class="guide cols2"><div class="guide col figcap"><p><img src="'+f+'" alt="" loading="lazy"></p><p>第三人称视角俯视角度：20</p></div><div class="guide col figcap"><p><img src="'+h+'" alt="" loading="lazy"></p><p>第三人称视角俯视角度：80</p></div></div><blockquote><p><a href="/basic/config.htm">想了解更多关于游戏设置的内容</a>：完整介绍了游戏设置中所有的设置选项。</p></blockquote>',15))])}const D=e(x,[["render",j]]);export{z as __pageData,D as default};
